    static void draw(GuiGraphics g, String name, int x, int y, int scale) {
        if(name.equals("Chromium")){LaptopAppIcons.draw(g,24,x,y,16*scale);return;}
        int index = switch(name) {
            case "Calculator" -> 0; case "Notes" -> 1; case "Clock" -> 2; case "Flashlight" -> 3;
            case "Settings" -> 4; case "Camera" -> 5; case "Messages" -> 6; case "Gallery" -> 7; case "Security" -> 9; default -> 8;
        };
        int[] pixels = PIXELS[index];
        for (int row=0; row<16; row++) for (int col=0; col<16; col++) {
            int color=pixels[row*16+col];
            if ((color >>> 24) != 0) g.fill(x+col*scale,y+row*scale,x+(col+1)*scale,y+(row+1)*scale,color);
        }
    }
